SELECT COUNT(*)
FROM rectification_notice
WHERE alert_id = #{alertId}

SELECT COUNT(*)
FROM rectification_material
WHERE alert_id = #{alertId}

mapper.update:
UPDATE supervision_scan_run
SET status = 'FAILED',
    finished_at = #{finishedAt},
    failure_summary = #{failureSummary}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE supervision_scan_run
SET status = 'FAILED',
    finished_at = #{finishedAt},
    failure_summary = #{failureSummary}
WHERE status = 'RUNNING'
  AND started_at < #{staleBefore}

mapper.select:
SELECT FROM supervision_alert sa JOIN school s ON s.id = sa.school_id JOIN course_offering o ON o.id = sa.offering_id JOIN course c ON c.id = o.course_id JOIN teacher t ON t.id = o.teacher_id LEFT JOIN academic_term at ON at.id = o.term_id LEFT JOIN lesson_session ls ON ls.id = sa.session_id
sa.school_id = #{schoolId}
AND sa.alert_type = #{alertType}
AND sa.status = #{status}
AND sa.detected_at >= #{detectedFrom}
AND sa.detected_at <= #{detectedTo}
ORDER BY CASE sa.status WHEN 'OPEN' THEN 1 WHEN 'RETURNED' THEN 2 WHEN 'RECTIFYING' THEN 3 WHEN 'WAITING_VERIFY' THEN 4 WHEN 'ACKNOWLEDGED' THEN 5 ELSE 6 END, sa.rectification_deadline, sa.id DESC

SELECT id, school_id, status
FROM supervision_alert
WHERE id = #{id}

      AND school_id = #{schoolId}

FOR UPDATE

SELECT id, school_id, status
FROM supervision_alert
WHERE id = #{id}

      AND school_id = #{schoolId}

SELECT saa.id, saa.alert_id AS alertId, saa.from_status AS fromStatus, saa.to_status AS toStatus, saa.action_type AS actionType, saa.comment, saa.actor_id AS actorId, CASE WHEN saa.actor_role = 'SYSTEM' THEN '系统任务' ELSE u.display_name END AS actorName, saa.actor_role AS actorRole, saa.acted_at AS actedAt FROM supervision_alert_action saa JOIN supervision_alert sa ON sa.id = saa.alert_id AND sa.school_id = saa.school_id LEFT JOIN sys_user u ON u.id = saa.actor_id WHERE saa.alert_id = #{alertId}
AND saa.school_id = #{schoolId}
ORDER BY saa.acted_at, saa.id
